34	/**
35	 * Run one Boardroom seat with a hard timeout (ISSUE-1665). Unlike a bare
36	 * Promise.race, the timeout aborts the seat's work, clears its timer, and
37	 * marks it settled so late stream tokens cannot overwrite the timeout message.
38	 */
39	export function runSeatWithTimeout<T>(
40	    run: (control: SeatRunControl) => Promise<T>,
41	    { timeoutMs = BOARDROOM_SEAT_TIMEOUT_MS, parentSignal }: { timeoutMs?: number; parentSignal?: AbortSignal } = {},
42	): Promise<T> {
43	    const controller = new AbortController();
44	    let live = true;
45	    const onParentAbort = () => controller.abort(parentSignal?.reason);
46	    if (parentSignal?.aborted) controller.abort(parentSignal.reason);
47	    else parentSignal?.addEventListener('abort', onParentAbort, { once: true });
48	
49	    return new Promise<T>((resolve, reject) => {
50	        const timer = setTimeout(() => {
51	            if (!live) return;
52	            live = false;
53	            const error = new Error(`Agent execution timed out (${Math.round(timeoutMs / 1000)}s)`);
54	            controller.abort(error);
55	            reject(error);
56	        }, timeoutMs);
57	
58	        const settle = () => {
59	            live = false;
60	            clearTimeout(timer);
61	            parentSignal?.removeEventListener('abort', onParentAbort);
62	        };
63	
64	        run({ signal: controller.signal, isLive: () => live }).then(
65	            value => { if (live) { settle(); resolve(value); } else settle(); },
66	            error => { if (live) { settle(); reject(error); } else settle(); },
67	        );
68	    });
69	}
