 9	 * but is not shared with other tabs or devices, so only this tab's own
10	 * orphaned lease is ever released.
11	 */
12	const STORAGE_KEY = 'indii:boardroom:activeDispatchLease';
13	
14	/** Leases owned by a run that is still executing in this page. */
15	const liveLeases = new Set<string>();
