25	export function rememberBoardroomLease(leaseId: string): void {
26	    liveLeases.add(leaseId);
27	    try {
28	        storage()?.setItem(STORAGE_KEY, leaseId);
29	    } catch (error) {
30	        logger.warn('[BoardroomLease] Could not persist dispatch lease id:', error);
31	    }
32	}
