39	export function forgetBoardroomLease(leaseId: string): void {
40	    liveLeases.delete(leaseId);
41	    try {
42	        const store = storage();
43	        if (store?.getItem(STORAGE_KEY) === leaseId) store.removeItem(STORAGE_KEY);
44	    } catch (error) {
45	        logger.warn('[BoardroomLease] Could not clear dispatch lease id:', error);
46	    }
