1433	      ? activeLease.remainingSlotsByAgent as Record<string, unknown>
1434	      : {};
1435	    if (executedAgentIds.some(agentId => Number(remainingSlotsByAgent[agentId]) >= BOARDROOM_MAX_ITERATIONS_PER_AGENT)) {
