const assert = require('node:assert/strict');
const {readFileSync} = require('node:fs');
const {execFileSync} = require('node:child_process');
const ts = require('typescript');
const file = 'packages/firebase/src/functions/billing/enforceOperationCost.ts';
const name = 'completeBoardroomDispatchLease';
function load(source, lease, imageStatus) {
  const tree = ts.createSourceFile(file, source, ts.ScriptTarget.Latest, true);
  const declaration = tree.statements.find(statement => ts.isFunctionDeclaration(statement) && statement.name?.text === name);
  const js = ts.transpile(declaration.getText(tree).replace(/^export /, ''), {target: ts.ScriptTarget.ESNext});
  let stored = lease;
  const db = {doc: path => path, runTransaction: work => work({
    get: async path => ({exists: true, data: () => path.startsWith('users/') ? {activeLease: stored} : {status: imageStatus} }),
    set: (_, values) => { stored = values.activeLease; },
  })};
  const complete = new Function('admin', 'FieldValue', 'BOARDROOM_MAX_ITERATIONS_PER_AGENT', js + '\\nreturn ' + name)({firestore: () => db}, {serverTimestamp: () => undefined}, 2);
  return {complete, get: () => stored};
}
(async () => {
  const before = execFileSync('git', ['show', 'HEAD:' + file], {encoding: 'utf8'});
  const after = readFileSync(file, 'utf8');
  const params = {userId: 'fixture', leaseId: 'lease', abandoned: true};
  const lease = {id: 'lease', executedAgentIds: ['specialist'], remainingSlotsByAgent: {specialist: 2}, reservationIds: []};
  await assert.rejects(load(before, lease).complete(params), /before every planned agent starts/);
  const released = load(after, lease);
  await released.complete(params);
